package org.zhixiaoce.aperture;
import java.util.*;import java.time.*;import java.net.*;import java.nio.charset.StandardCharsets;import com.sun.net.httpserver.HttpServer;import org.json.*;
public class PlaybackPromotionTest {
 static int checks;interface Run{void run()throws Exception;}static void check(boolean b,String n){if(!b)throw new AssertionError(n);checks++;}static void rejects(Run r,String n)throws Exception{try{r.run();}catch(Exception e){checks++;return;}throw new AssertionError(n);}
 static CinemaCatalog.Line line(String label,String...names){List<CinemaCatalog.Episode> e=new ArrayList<>();for(String n:names)e.add(new CinemaCatalog.Episode(n,"https://example.invalid/video.mp4"));CinemaCatalog.Line line=new CinemaCatalog.Line(label);line.episodes.addAll(e);return line;}
 public static void main(String[] args)throws Exception{
  CinemaPlaybackPlan p=new CinemaPlaybackPlan(Arrays.asList(line("web","第01集","第02集"),line("stream","第1集","第2集"),line("wrong","预告","番外")),0,1,32000);
  check(p.next()&&p.line==1&&p.episode==1&&p.resume==32000,"fallback matches episode and preserves resume");check(!p.next(),"never switch to unrelated episode or retry failed line");check(p.choose(0)&&p.episode==1,"manual line switching matches current episode");check(CinemaPlaybackPlan.key("第01集：很长的完整节目标题").equals(CinemaPlaybackPlan.key("备用线路 · 第1集")),"full titles retain episode mapping");
  check(new CinemaPlaybackPlan(Arrays.asList(line("1","正片"),line("2","HD")),0,0,0).next(),"single film fallback");check(!new CinemaPlaybackPlan(Arrays.asList(line("1","第01集"),line("2","第1集","第01集")),0,0,0).next(),"ambiguous match rejected");
  String json="{\"version\":1,\"timezone\":\"Asia/Shanghai\",\"messages\":[{\"id\":\"m1\",\"text\":\"饭后散步\",\"time\":\"20:00-20:30\",\"repeat\":\"daily\",\"tts\":true,\"expireAt\":\"2026-11-02T00:00:00+08:00\"}]}";
  MessageFeed feed=new MessageFeed(json);JSONObject m=feed.messages.get(0);check(feed.due(m,Instant.parse("2026-10-31T12:00:20Z")).equals("m1:2026-10-31:20:00"),"timezone scheduled range begins once");check(feed.due(m,Instant.parse("2026-10-31T12:01:00Z")).isEmpty(),"no stale catch-up");check(!feed.visible(m,Instant.parse("2026-11-02T00:00:00Z")),"expired cache hidden");
  rejects(()->new MessageFeed(json.replace("daily","once")),"once requires date");rejects(()->new MessageFeed(json.replace("20:00-20:30","25:00")),"invalid time");check(MessageFeed.source("https://example.invalid/feed.json").startsWith("https:"),"https feed");rejects(()->MessageFeed.source("http://example.invalid/"),"reject insecure feed");rejects(()->MessageFeed.source("https://user:secret@example.invalid/"),"reject embedded credential");check(!feed.display(Instant.now()).toString().contains("author"),"display excludes author");
  HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",x->{String path=x.getRequestURI().getPath();try{if(path.equals("/slow"))Thread.sleep(12500);}catch(InterruptedException e){Thread.currentThread().interrupt();}if(path.equals("/redirect")){x.getResponseHeaders().set("Location","/video");x.sendResponseHeaders(302,-1);}else{byte[] bytes=path.equals("/video")||path.equals("/slow")?new byte[]{0,0,0,20,'f','t','y','p',1,2,3}:"<!doctype html><html>not video</html>".getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type",path.equals("/slow")?"video/mp4":path.equals("/video")?"application/octet-stream":"text/html");x.sendResponseHeaders(200,bytes.length);x.getResponseBody().write(bytes);}x.close();});server.start();
  try{String base="http://127.0.0.1:"+server.getAddress().getPort();CinemaHttp http=new CinemaHttp();rejects(()->http.media(new CinemaCatalog.Episode("film",base+"/html"),true),"HTTP 200 HTML rejected");rejects(()->http.media(new CinemaCatalog.Episode("film",base+"/share/123"),true),"share URL skipped");check(http.media(new CinemaCatalog.Episode("film",base+"/redirect"),true).url.endsWith("/video"),"media redirect retained");long start=System.nanoTime();http.media(new CinemaCatalog.Episode("film",base+"/slow"),true);check(System.nanoTime()-start>12_000_000_000L,"media probe waits at least 12s without false 8s failure");rejects(()->http.media(new CinemaCatalog.Episode("film",base+"/video"),false),"HTTP media consent retained");}finally{server.stop(0);}
  System.out.println(checks+" promotion playback/message assertions passed; decoder and Xiaomi acceptance excluded");
 }
}
